-- =====================================================================================
-- The Playroom — PostgreSQL schema
--
-- Fresh deployment:
--   createdb playroom
--   psql "$DATABASE_URL" -f database.sql        (or: npm run db:init)
--   npm run db:seed                              (optional demo data)
--
-- Conventions
--   * ids are text (generated by the app, e.g. "tk…", "c…")
--   * money is numeric(14,2); timestamps are timestamptz; calendar dates are date; clock times are 'HH:MM' text
--   * every business table has a `seq` column so lists come back in insertion order
--   * user_id / created_by columns on history tables are plain text: they may hold 'system'
--     (online bookings, kiosk scans) and must survive a user being removed
-- =====================================================================================

BEGIN;

-- Bumped by every write; open screens poll it to know when to refresh.
CREATE SEQUENCE state_rev START WITH 1;

-- ---------------------------------------------------------------- access control

CREATE TABLE roles (
  id          text PRIMARY KEY,
  name        text NOT NULL,
  description text NOT NULL DEFAULT '',
  permissions text[] NOT NULL DEFAULT '{}',
  locked      boolean,                         -- true = full access, can't be edited (Owner)
  seq         bigserial NOT NULL
);

CREATE TABLE users (
  id                   text PRIMARY KEY,
  name                 text NOT NULL,
  username             text NOT NULL,
  email                text NOT NULL DEFAULT '',
  phone                text NOT NULL DEFAULT '',
  role_id              text NOT NULL REFERENCES roles (id),
  active               boolean NOT NULL DEFAULT true,
  password_hash        text NOT NULL,           -- scrypt$<salt>$<hash>
  must_change_password boolean,
  last_login           timestamptz,
  created_at           timestamptz NOT NULL,
  employee_id          text,                    -- the Staff record this login belongs to (none for e.g. an outside accountant)
  seq                  bigserial NOT NULL,
  CONSTRAINT users_username_unique UNIQUE (username),
  CONSTRAINT users_employee_unique UNIQUE (employee_id)
);
CREATE UNIQUE INDEX users_username_lower_idx ON users (lower(username));

CREATE TABLE sessions (
  id         text PRIMARY KEY,                  -- sha-256 of the cookie token
  user_id    text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL
);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);

-- ---------------------------------------------------------------- venue & pricing

CREATE TABLE zones (
  id            text PRIMARY KEY,
  name          text NOT NULL,
  kind          text NOT NULL CHECK (kind IN ('play', 'party', 'cowork')),
  capacity      integer NOT NULL CHECK (capacity >= 0),
  near_full_pct numeric(14, 2) NOT NULL,
  open_time     text NOT NULL,
  close_time    text NOT NULL,
  min_age       integer,
  max_age       integer,
  rules         text NOT NULL DEFAULT '',
  active        boolean NOT NULL DEFAULT true,
  color         text NOT NULL,
  seq           bigserial NOT NULL
);

-- one rate per zone: the price per 30 minutes; a stay is charged in 30-minute blocks, rounded up
CREATE TABLE rate_plans (
  id      text PRIMARY KEY,
  zone_id text NOT NULL UNIQUE,
  price   numeric(14, 2) NOT NULL,
  active  boolean NOT NULL DEFAULT true,
  seq     bigserial NOT NULL
);

CREATE TABLE price_rules (
  id       text PRIMARY KEY,
  name     text NOT NULL,
  kind     text NOT NULL CHECK (kind IN ('weekday', 'weekend', 'peak', 'offpeak', 'holiday', 'event')),
  days     integer[] NOT NULL DEFAULT '{}',     -- 0 = Sunday
  start    text NOT NULL,
  "end"    text NOT NULL,
  date     date,                                -- event rules only
  adjust   text NOT NULL CHECK (adjust IN ('percent', 'fixed')),
  value    numeric(14, 2) NOT NULL,
  zone_ids text[] NOT NULL DEFAULT '{}',
  active   boolean NOT NULL DEFAULT true,
  seq      bigserial NOT NULL
);

CREATE TABLE promotions (
  id           text PRIMARY KEY,
  code         text NOT NULL,
  name         text NOT NULL,
  type         text NOT NULL CHECK (type IN ('percent', 'fixed', 'package', 'bonus_time')),
  value        numeric(14, 2) NOT NULL,
  package_kids integer,
  valid_from   date NOT NULL,
  valid_to     date NOT NULL,
  usage_cap    integer NOT NULL DEFAULT 0,      -- 0 = unlimited
  used         integer NOT NULL DEFAULT 0,
  auto         boolean NOT NULL DEFAULT false,
  active       boolean NOT NULL DEFAULT true,
  zone_ids     text[] NOT NULL DEFAULT '{}',
  targeting    jsonb NOT NULL DEFAULT '{}'::jsonb,
  seq          bigserial NOT NULL
);

-- ---------------------------------------------------------------- customers

CREATE TABLE customers (
  id         text PRIMARY KEY,
  name       text NOT NULL,
  phone      text NOT NULL,
  email      text NOT NULL DEFAULT '',
  address    text NOT NULL DEFAULT '',
  member     boolean NOT NULL DEFAULT false,
  points     integer NOT NULL DEFAULT 0,
  wallet     numeric(14, 2) NOT NULL DEFAULT 0,
  notes      text NOT NULL DEFAULT '',
  whatsapp_opt_out boolean NOT NULL DEFAULT false,  -- no promotions / birthday wishes (replied STOP or asked)
  created_at timestamptz NOT NULL,
  seq        bigserial NOT NULL
);
CREATE INDEX customers_phone_idx ON customers (phone);

CREATE TABLE children (
  id          text PRIMARY KEY,
  guardian_id text NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
  name        text NOT NULL,
  dob         date NOT NULL,
  gender      text NOT NULL CHECK (gender IN ('girl', 'boy', 'other')),
  allergies   text NOT NULL DEFAULT '',
  seq         bigserial NOT NULL
);
CREATE INDEX children_guardian_id_idx ON children (guardian_id);

-- ---------------------------------------------------------------- tickets & money

CREATE TABLE tickets (
  id           text PRIMARY KEY,
  code         text NOT NULL,
  customer_id  text NOT NULL,
  child_ids    text[] NOT NULL DEFAULT '{}',
  visitors     integer NOT NULL,
  adults       integer NOT NULL DEFAULT 0,
  zone_id      text NOT NULL,
  rate_plan_id text,                             -- the zone's rate used at check-out
  minutes      integer NOT NULL DEFAULT 0,       -- minutes stayed (filled in at check-out)
  visit_id     text,                             -- play + co-work tickets of one visit share it (the first ticket's code)
  check_in     timestamptz NOT NULL,
  check_out    timestamptz,
  status       text NOT NULL CHECK (status IN ('active', 'completed', 'cancelled', 'expired', 'refunded')),
  base         numeric(14, 2) NOT NULL,
  rule_adjust  numeric(14, 2) NOT NULL DEFAULT 0,
  rule_names   text[] NOT NULL DEFAULT '{}',
  promo_id     text,
  discount     numeric(14, 2) NOT NULL DEFAULT 0,
  loyalty_used numeric(14, 2) NOT NULL DEFAULT 0,
  overtime_fee numeric(14, 2) NOT NULL DEFAULT 0,  -- no longer charged; kept for older tickets and backups
  total        numeric(14, 2) NOT NULL,
  paid         numeric(14, 2) NOT NULL DEFAULT 0,
  created_by   text NOT NULL,
  reprints     integer NOT NULL DEFAULT 0,
  booking_id   text,
  seq          bigserial NOT NULL,
  CONSTRAINT tickets_code_unique UNIQUE (code)
);
CREATE INDEX tickets_status_idx ON tickets (status);
CREATE INDEX tickets_customer_id_idx ON tickets (customer_id);
CREATE INDEX tickets_visit_id_idx ON tickets (visit_id);

-- Every payment in or out (refunds are negative). The basis of shift reports, cash flow and P&L.
CREATE TABLE transactions (
  id           text PRIMARY KEY,
  at           timestamptz NOT NULL,
  type         text NOT NULL CHECK (type IN ('play', 'cowork', 'overtime', 'deposit', 'party', 'pos', 'topup', 'refund')),
  method       text NOT NULL CHECK (method IN ('cash', 'card', 'transfer', 'digital', 'wallet', 'online')),
  amount       numeric(14, 2) NOT NULL,
  ref          text NOT NULL,                   -- ticket / sale / booking / customer id
  ref_label    text NOT NULL,
  customer_id  text,
  shift_id     text,
  user_id      text NOT NULL,
  discount     numeric(14, 2) NOT NULL DEFAULT 0,
  revenue_type text,                            -- refunds: which revenue stream is reversed
  seq          bigserial NOT NULL
);
CREATE INDEX transactions_at_idx ON transactions (at);
CREATE INDEX transactions_ref_idx ON transactions (ref);
CREATE INDEX transactions_shift_id_idx ON transactions (shift_id);

CREATE TABLE products (
  id         text PRIMARY KEY,
  name       text NOT NULL,
  category   text NOT NULL,
  sku        text NOT NULL DEFAULT '',
  price      numeric(14, 2) NOT NULL,
  cost       numeric(14, 2) NOT NULL DEFAULT 0,
  stock      integer NOT NULL DEFAULT 0,
  reorder_at integer NOT NULL DEFAULT 0,
  active     boolean NOT NULL DEFAULT true,
  seq        bigserial NOT NULL
);

CREATE TABLE sales (
  id          text PRIMARY KEY,
  no          text NOT NULL,
  at          timestamptz NOT NULL,
  items       jsonb NOT NULL,                   -- [{ productId, name, qty, price, cost }]
  subtotal    numeric(14, 2) NOT NULL,
  discount    numeric(14, 2) NOT NULL DEFAULT 0,
  total       numeric(14, 2) NOT NULL,
  method      text NOT NULL CHECK (method IN ('cash', 'card', 'transfer', 'digital', 'wallet')),
  tendered    numeric(14, 2) NOT NULL,
  user_id     text NOT NULL,
  shift_id    text,
  customer_id text,
  refunded    numeric(14, 2),
  seq         bigserial NOT NULL,
  CONSTRAINT sales_no_unique UNIQUE (no)
);
CREATE INDEX sales_at_idx ON sales (at);

CREATE TABLE shifts (
  id            text PRIMARY KEY,
  user_id       text NOT NULL,
  opened_at     timestamptz NOT NULL,
  closed_at     timestamptz,
  opening_float numeric(14, 2) NOT NULL,
  counted_cash  numeric(14, 2),
  notes         text NOT NULL DEFAULT '',
  seq           bigserial NOT NULL
);
-- one open shift per cashier
CREATE UNIQUE INDEX shifts_one_open_per_user_idx ON shifts (user_id) WHERE closed_at IS NULL;

CREATE TABLE refunds (
  id           text PRIMARY KEY,
  at           timestamptz NOT NULL,
  target       text NOT NULL CHECK (target IN ('ticket', 'sale', 'booking')),
  target_id    text NOT NULL,
  label        text NOT NULL,
  max_amount   numeric(14, 2) NOT NULL,
  amount       numeric(14, 2) NOT NULL CHECK (amount > 0),
  "full"       boolean NOT NULL,
  category     text CHECK (category IN ('overcharge', 'service', 'left_early', 'duplicate', 'cancelled', 'other')),
  reason       text NOT NULL,
  method       text NOT NULL CHECK (method IN ('cash', 'card', 'transfer', 'digital', 'wallet')),
  requested_by text NOT NULL,
  status       text NOT NULL CHECK (status IN ('pending', 'approved', 'rejected')),
  decided_by   text,
  decided_at   timestamptz,
  seq          bigserial NOT NULL
);
CREATE INDEX refunds_target_id_idx ON refunds (target_id);

-- ---------------------------------------------------------------- parties & bookings

CREATE TABLE party_packages (
  id                text PRIMARY KEY,
  name              text NOT NULL,
  room_zone_id      text NOT NULL,
  guest_limit       integer NOT NULL,
  duration_min      integer NOT NULL,
  price_room_only   numeric(14, 2) NOT NULL,
  price_full_venue  numeric(14, 2) NOT NULL,
  extra_guest_price numeric(14, 2) NOT NULL,
  deposit_pct       numeric(14, 2) NOT NULL,
  includes          text[] NOT NULL DEFAULT '{}',
  active            boolean NOT NULL DEFAULT true,
  overtime_room_per_hour numeric(14, 2) NOT NULL DEFAULT 0,   -- staying past the end: per hour, charged per started 30 min
  overtime_full_per_hour numeric(14, 2) NOT NULL DEFAULT 0,
  overtime_grace_min     integer NOT NULL DEFAULT 10,         -- minutes past the end that are free
  seq               bigserial NOT NULL
);

CREATE TABLE addons (
  id       text PRIMARY KEY,
  name     text NOT NULL,
  kind     text NOT NULL CHECK (kind IN ('addon', 'food', 'decor')),
  price    numeric(14, 2) NOT NULL,
  per_head boolean NOT NULL DEFAULT false,
  active   boolean NOT NULL DEFAULT true,
  seq      bigserial NOT NULL
);

CREATE TABLE bookings (
  id          text PRIMARY KEY,
  ref         text NOT NULL,
  kind        text NOT NULL CHECK (kind IN ('play', 'party', 'cowork')),
  mode        text CHECK (mode IN ('room', 'full')),   -- party: room only / full venue (locks the play area)
  customer_id text NOT NULL,
  date        date NOT NULL,
  start       text NOT NULL,
  "end"       text NOT NULL,
  zone_id     text NOT NULL,
  package_id  text,
  guests      integer NOT NULL,
  kids        integer NOT NULL,
  addon_ids   text[] NOT NULL DEFAULT '{}',
  theme       text NOT NULL DEFAULT '',
  notes       text NOT NULL DEFAULT '',
  total       numeric(14, 2) NOT NULL,
  adjustment  numeric(14, 2),
  deposit     numeric(14, 2) NOT NULL DEFAULT 0,
  paid        numeric(14, 2) NOT NULL DEFAULT 0,
  status      text NOT NULL CHECK (status IN ('pending', 'confirmed', 'completed', 'cancelled')),
  source      text NOT NULL CHECK (source IN ('walkin', 'online', 'phone')),
  created_at  timestamptz NOT NULL,
  checked_in_at   timestamptz,                      -- party arrived (booking QR scanned)
  checked_out_at  timestamptz,                      -- party left
  overtime_min    integer,                          -- minutes past the booked end at check-out
  overtime_charge numeric(14, 2),                   -- charged for them (already in total)
  seq         bigserial NOT NULL,
  CONSTRAINT bookings_ref_unique UNIQUE (ref)
);
CREATE INDEX bookings_date_idx ON bookings (date);

-- ---------------------------------------------------------------- finance & HR

CREATE TABLE expenses (
  id             text PRIMARY KEY,
  date           date NOT NULL,
  category       text NOT NULL,
  description    text NOT NULL,
  vendor         text NOT NULL DEFAULT '',
  amount         numeric(14, 2) NOT NULL,
  paid_from      text NOT NULL CHECK (paid_from IN ('cash', 'bank')),
  payroll_run_id text,
  created_by     text NOT NULL,
  seq            bigserial NOT NULL
);
CREATE INDEX expenses_date_idx ON expenses (date);

CREATE TABLE employees (
  id          text PRIMARY KEY,
  code        text NOT NULL,
  name        text NOT NULL,
  designation text NOT NULL DEFAULT '',
  phone       text NOT NULL DEFAULT '',
  nic         text NOT NULL DEFAULT '',
  join_date   date NOT NULL,
  basic       numeric(14, 2) NOT NULL,             -- monthly basic (permanent staff)
  employment_type text NOT NULL DEFAULT 'permanent' CHECK (employment_type IN ('permanent', 'non_permanent', 'part_time')),
  pay_basis   text NOT NULL DEFAULT 'monthly' CHECK (pay_basis IN ('monthly', 'daily', 'hourly')),  -- any employment type can be paid any way
  rate        numeric(14, 2) NOT NULL DEFAULT 0,   -- pay per day (daily) or per hour (hourly)
  allowances  jsonb NOT NULL DEFAULT '[]',         -- fixed monthly allowances: [{ name, amount, epf }]
  deductions  jsonb NOT NULL DEFAULT '[]',         -- recurring monthly deductions: [{ name, amount }]
  ot_rate     numeric(14, 2) NOT NULL DEFAULT 0,   -- per hour
  epf         boolean NOT NULL DEFAULT true,
  etf         boolean NOT NULL DEFAULT true,
  epf_no      text NOT NULL DEFAULT '',
  bank        text NOT NULL DEFAULT '',
  active      boolean NOT NULL DEFAULT true,
  qr_token    text NOT NULL,                       -- badge content: PLAYROOM-STAFF:<qr_token>
  color       text NOT NULL,
  work_hours  jsonb,                               -- { start, end, days: [0-6], graceMin } for late / early arrivals
  qualifications jsonb NOT NULL DEFAULT '[]',      -- [{ id, title, institution, year, notes }]
  seq         bigserial NOT NULL,
  CONSTRAINT employees_qr_token_unique UNIQUE (qr_token)
);

CREATE TABLE attendance (
  id          text PRIMARY KEY,
  employee_id text NOT NULL REFERENCES employees (id) ON DELETE CASCADE,
  date        date NOT NULL,
  clock_in    timestamptz NOT NULL,
  clock_out   timestamptz,
  method      text NOT NULL CHECK (method IN ('qr', 'manual')),
  scheduled_in text,                               -- the start time it was measured against ("HH:mm")
  in_diff_min integer,                             -- minutes after the scheduled start (negative = early)
  punctuality text CHECK (punctuality IN ('early', 'on_time', 'late', 'off_day')),
  seq         bigserial NOT NULL
);
CREATE INDEX attendance_employee_id_date_idx ON attendance (employee_id, date);

-- training sessions the company ran or paid for, and who attended
CREATE TABLE trainings (
  id           text PRIMARY KEY,
  title        text NOT NULL,
  date         date NOT NULL,
  trainer      text NOT NULL DEFAULT '',
  hours        numeric(8, 2) NOT NULL DEFAULT 0,
  description  text NOT NULL DEFAULT '',
  employee_ids jsonb NOT NULL DEFAULT '[]',
  seq          bigserial NOT NULL
);

-- KPI marks (0-10) per employee and month; the KPIs themselves are in settings
CREATE TABLE evaluations (
  id           text PRIMARY KEY,                  -- ev-<employee id>-<yyyy-MM>
  employee_id  text NOT NULL,
  period       text NOT NULL,                     -- yyyy-MM
  scores       jsonb NOT NULL DEFAULT '{}',       -- { <kpi id>: 0-10 }
  notes        text NOT NULL DEFAULT '',
  evaluated_by text NOT NULL DEFAULT '',
  at           timestamptz NOT NULL DEFAULT now(),
  seq          bigserial NOT NULL
);
CREATE INDEX evaluations_employee_id_period_idx ON evaluations (employee_id, period);

CREATE TABLE payroll_runs (
  id         text PRIMARY KEY,
  month      text NOT NULL,                       -- yyyy-MM
  status     text NOT NULL CHECK (status IN ('draft', 'paid')),
  lines      jsonb NOT NULL,                      -- one pay line per employee
  created_at timestamptz NOT NULL,
  paid_at    timestamptz,
  created_by text NOT NULL,
  seq        bigserial NOT NULL,
  CONSTRAINT payroll_runs_month_unique UNIQUE (month)
);

-- ---------------------------------------------------------------- audit, settings, backups

CREATE TABLE activity (
  id      text PRIMARY KEY,
  at      timestamptz NOT NULL,
  user_id text NOT NULL,
  module  text NOT NULL,
  action  text NOT NULL,
  detail  text NOT NULL DEFAULT '',
  before  text,
  after   text,
  seq     bigserial NOT NULL
);
CREATE INDEX activity_at_idx ON activity (at);
CREATE INDEX activity_user_id_idx ON activity (user_id);

-- Business settings are a single JSON document (row id = 1).
CREATE TABLE settings (
  id   integer PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  data jsonb NOT NULL
);

CREATE TABLE backups (
  id         text PRIMARY KEY,
  at         timestamptz NOT NULL,
  size       integer NOT NULL,
  auto       boolean NOT NULL,
  snapshot   jsonb,                               -- full data export; NULL for placeholder entries
  created_by text,
  seq        bigserial NOT NULL
);
CREATE INDEX backups_at_idx ON backups (at);

-- ---------------------------------------------------------------- WhatsApp (linked device, scanned by QR)

-- Login state of the linked WhatsApp account (Baileys credentials and signal keys, JSON text).
CREATE TABLE whatsapp_auth (
  key   text PRIMARY KEY,
  value text NOT NULL
);

-- Outgoing messages: a queue the server works through slowly, and the log of what was sent.
CREATE TABLE whatsapp_messages (
  id          text PRIMARY KEY,
  created_at  timestamptz NOT NULL DEFAULT now(),
  kind        text NOT NULL CHECK (kind IN ('checkin', 'receipt', 'birthday', 'promotion', 'manual', 'staff')),  -- staff: alerts to staff phones
  customer_id text,
  child_id    text,                               -- birthday wishes: which child
  to_phone    text NOT NULL,                      -- international digits, e.g. 94771234567
  body        text NOT NULL,
  media       jsonb,                              -- e.g. {"type":"qr","data":"PR261022-0001"}
  campaign    text,
  priority    integer NOT NULL DEFAULT 5,         -- lower goes first: receipts before bulk promotions
  status      text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'sending', 'sent', 'failed', 'cancelled')),
  error       text,
  attempts    integer NOT NULL DEFAULT 0,
  sent_at     timestamptz,
  created_by  text NOT NULL,
  seq         bigserial NOT NULL
);
CREATE INDEX whatsapp_messages_status_idx ON whatsapp_messages (status, priority, seq);
CREATE INDEX whatsapp_messages_created_at_idx ON whatsapp_messages (created_at);
CREATE INDEX whatsapp_messages_child_idx ON whatsapp_messages (kind, child_id);

-- ---------------------------------------------------------------- change tracking
-- Every write stamps the rows it touched with the new state revision (in commit order), so open screens
-- download only what changed since their last refresh instead of the whole data set.
ALTER TABLE roles ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS roles_rev_idx ON roles (rev);
ALTER TABLE users ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS users_rev_idx ON users (rev);
ALTER TABLE zones ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS zones_rev_idx ON zones (rev);
ALTER TABLE rate_plans ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS rate_plans_rev_idx ON rate_plans (rev);
ALTER TABLE price_rules ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS price_rules_rev_idx ON price_rules (rev);
ALTER TABLE promotions ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS promotions_rev_idx ON promotions (rev);
ALTER TABLE customers ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS customers_rev_idx ON customers (rev);
ALTER TABLE children ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS children_rev_idx ON children (rev);
ALTER TABLE tickets ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS tickets_rev_idx ON tickets (rev);
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS transactions_rev_idx ON transactions (rev);
ALTER TABLE products ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS products_rev_idx ON products (rev);
ALTER TABLE sales ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS sales_rev_idx ON sales (rev);
ALTER TABLE party_packages ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS party_packages_rev_idx ON party_packages (rev);
ALTER TABLE addons ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS addons_rev_idx ON addons (rev);
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS bookings_rev_idx ON bookings (rev);
ALTER TABLE shifts ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS shifts_rev_idx ON shifts (rev);
ALTER TABLE refunds ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS refunds_rev_idx ON refunds (rev);
ALTER TABLE expenses ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS expenses_rev_idx ON expenses (rev);
ALTER TABLE employees ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS employees_rev_idx ON employees (rev);
ALTER TABLE attendance ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS attendance_rev_idx ON attendance (rev);
ALTER TABLE payroll_runs ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS payroll_runs_rev_idx ON payroll_runs (rev);
ALTER TABLE activity ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS activity_rev_idx ON activity (rev);
ALTER TABLE trainings ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS trainings_rev_idx ON trainings (rev);
ALTER TABLE evaluations ADD COLUMN IF NOT EXISTS rev bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS evaluations_rev_idx ON evaluations (rev);

-- deleted records, so screens can drop them too
CREATE TABLE IF NOT EXISTS deleted_rows (
  collection text NOT NULL,
  id         text NOT NULL,
  rev        bigint NOT NULL,
  PRIMARY KEY (collection, id)
);
CREATE INDEX IF NOT EXISTS deleted_rows_rev_idx ON deleted_rows (rev);

-- the last committed revision; settings_rev / reset_rev: when settings last changed / everything was replaced
CREATE TABLE IF NOT EXISTS state_version (
  id           int PRIMARY KEY CHECK (id = 1),
  rev          bigint NOT NULL,
  settings_rev bigint NOT NULL DEFAULT 0,
  reset_rev    bigint NOT NULL DEFAULT 0
);
-- an existing database: every screen does one full reload after the upgrade
INSERT INTO state_version (id, rev, settings_rev, reset_rev) SELECT 1, nextval('state_rev'), currval('state_rev'), currval('state_rev') ON CONFLICT (id) DO NOTHING;

-- Default business settings so a fresh install works before anything is configured.
INSERT INTO settings (id, data) VALUES (1, '{
  "businessName": "The Playroom",
  "address": "",
  "phone": "",
  "email": "",
  "receiptFooter": "Play, Grow, Shine! Thank you for visiting.",
  "pointsPer100": 1,
  "pointValue": 1,
  "refundNeedsApproval": true,
  "priceEditNeedsPermission": true,
  "epfEnabled": true,
  "etfEnabled": true,
  "epfEmployeePct": 8,
  "epfEmployerPct": 12,
  "etfPct": 3,
  "epfIncludesAllowance": false,
  "workStart": "09:00",
  "standardHours": 8,
  "openingCash": 0,
  "holidays": []
}'::jsonb);

COMMIT;
